import{_ as n,a0 as p,w as g,s,I as a,x as o,a1 as l,A as r,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux 系統中使用 logwatch 監控日誌文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系統中使用 logwatch 監控日誌文件 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系統中使用 logwatch 監控日誌文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系統中使用 logwatch 監控日誌文件 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141021 How to monitor a log file on Linux with logwatch","title":"Linux 系統中使用 logwatch 監控日誌文件","tag":"201412","desc":""},"relativePath":"201412/20141021 How to monitor a log file on Linux with logwatch.md","filePath":"[post].md"}'),c={name:"201412/20141021 How to monitor a log file on Linux with logwatch.md"};function d(h,t,u,w,m,f){const e=p("Link");return g(),s("div",null,[t[18]||(t[18]=a("h1",{id:"linux-系統中使用-logwatch-監控日誌文件",tabindex:"-1"},[o("Linux 系統中使用 logwatch 監控日誌文件 "),a("a",{class:"header-anchor",href:"#linux-系統中使用-logwatch-監控日誌文件","aria-label":"Permalink to “Linux 系統中使用 logwatch 監控日誌文件”"},"​")],-1)),t[19]||(t[19]=a("p",null,"Linux 操作系統和許多應用程序會創建特殊的文件來記錄它們的運行事件，這些文件通常被稱作“日誌”。當要了解操作系統或第三方應用程序的行為或進行故障排查時，這些系統日誌或特定的應用程序日誌文件是必不可少的的工具。但是，日誌文件並沒有您們所謂的“清晰”或“容易”這種程度的可讀性。手工分析原始的日誌文件簡直是浪費時間，並且單調乏味。出於這個原因，對於系統管理員來説，發現任何一款能把原始的日誌文件轉換成更人性化的記錄摘要的工具，將會受益無窮。",-1)),a("p",null,[l(e,{href:"http://sourceforge.net/projects/logwatch/"},{default:r(()=>[...t[0]||(t[0]=[o("logwatch",-1)])]),_:1}),t[1]||(t[1]=o(" 是一款用 Perl 語言編寫的開源日誌解析分析器。它能對原始的日誌文件進行解析並轉換成結構化格式的文檔，也能根據您的使用情況和需求來定製報告。logwatch 的主要目的是生成更易於使用的日誌摘要，並不是用來對日誌進行實時的處理和監控的。正因為如此，logwatch 通常被設定好時間和頻率的自動定時任務來調度運行或者是有需要日誌處理的時候從命令列裏手動運行。一旦日誌報告生成，logwatch 可以通過電子郵件把這報告發送給您，您可以把它保存成文件或者直接顯示在屏幕上。",-1))]),t[20]||(t[20]=i(`<p>Logwatch 報告的詳細程度和報告覆蓋範圍是完全可定製化的。Logwatch 的日誌處理引擎也是可擴展的，從某種意義上來説，如果您想在一個新的應用程序中使用 logwatch 功能的話，只需要為這個應用程序的日誌文件編寫一個日誌處理腳本（使用 Perl 語言），然後掛接到 logwatch 上就行。</p><p>logwatch 有一點不好的就是，在它生成的報告中沒有詳細的時間戳信息，而原來的日誌文件中是存在的。您只能知道被記錄下來的一段時間之內的特定事件，如果想要知道精確的時間點的信息，就不得不去查看原日誌文件了。</p><h3 id="安裝-logwatch" tabindex="-1">安裝 Logwatch <a class="header-anchor" href="#安裝-logwatch" aria-label="Permalink to “安裝 Logwatch”">​</a></h3><p>在 Debian 系統或其派生的系統上:</p><pre><code># aptitude install logwatch 
</code></pre><p>在基於 Red Hat 的發佈系統上:</p><pre><code># yum install logwatch 
</code></pre><h3 id="配置-logwatch" tabindex="-1">配置 Logwatch <a class="header-anchor" href="#配置-logwatch" aria-label="Permalink to “配置 Logwatch”">​</a></h3><p>安裝時，主要的配置文件（logwatch.conf）被放到 <strong>/etc/logwatch/conf</strong> 目錄中。此文件（默認是空的）定義的設置選項會覆蓋掉定義在 /usr/share/logwatch/default.conf/logwatch.conf 文件中的系統級設置。</p><p>在命令列中，啓動 logwatch, 如果不帶參數的話，將會使用 /etc/logwatch/conf/logwatch.conf 文件中定義的選項。但，只要一指定參數，它們就會覆蓋 /etc/logwatch/conf/logwatch.conf 文件中的任意默認/自定義設置。</p><p>這篇文章裏，我們會編輯 /etc/logwatch/conf/logwatch.conf 文件來對一些默認的設置項做些個性化設置。</p><pre><code>Detail = &lt;Low, Med, High, 或數字&gt;
</code></pre><p>“Detail” 配置指令控制着 logwatch 報告的詳細程度。它可以是個正整數，也可以是分別代表着10、5和0數字的 High、Med、Low 幾個選項。</p><pre><code>MailTo = youremailaddress@yourdomain.com
</code></pre><p>如果您讓把一份 logwatch 的報告郵件給您，就要使用 “MailTo” 這個配置指令。要把一份報告發送給多個用户，只需要把他們的郵件地址用空格格開，然後配置上去。但是，您需要在 logwatch 運行的服務器上配置好本地郵件傳輸代理（MTA）如，sendmail、 Postfix 等，這個配置指令項才能起作用。</p><pre><code>Range = &lt;Yesterday|Today|All&gt;
</code></pre><p>&quot;Range&quot; 配置指令定義了生成 logwatch 報告的時間段信息。這個指令通常可選的值是 Yesterday、Today、All。當作用了“Rang = All”時，“Archive = yes” 這個指令項也必須配置上，那麼所有的已存檔的日誌文件 (比如，/var/log/maillog、/var/log/maillog.X 或 /var/log/maillog.X.gz 文件)都會被處理到。</p><p>除了這些通用的 range 值，您也可以使用複雜點的選擇值，如下所示：</p><ul><li>Range = &quot;2 hours ago for that hour&quot;</li><li>Range = &quot;-5 days&quot;</li><li>Range = &quot;between -7 days and -3 days&quot;</li><li>Range = &quot;since September 15, 2014&quot;</li><li>Range = &quot;first Friday in October&quot;</li><li>Range = &quot;2014/10/15 12:50:15 for that second&quot;</li></ul>`,19)),a("p",null,[t[3]||(t[3]=o("要使用上面例子中自由形式的 range，您需要從 CPAN（注：Comprehensive　Perl　Archive　Network） 上下載安裝 Perl 的 Date::Manip 模組。關於 CPAN 模組的安裝説明，請請參閲",-1)),l(e,{href:"http://xmodulo.com/how-to-install-perl-modules-from-cpan.html"},{default:r(()=>[...t[2]||(t[2]=[o("此帖",-1)])]),_:1}),t[4]||(t[4]=o(" 。",-1))]),t[21]||(t[21]=i(`<pre><code>Service = &lt;service-name-1&gt;
Service = &lt;service-name-2&gt;
. . .
</code></pre><p>“Service” 選項指定想要監控的一個或多個服務。在 /usr/share/logwatch/scripts/services 目錄下列出的服務都能被監控，它們已經涵蓋了重要的系統服務（例如：pam,secure,iptables,syslogd 等），也涵蓋了一些像 sudo、sshd、http、fail2ban、samba等主流的應用服務。如果您想添加新的服務到列表中，得編寫一個相應的日誌處理 Perl 腳本，並把它放在這個目錄中。</p><p>如果這個選項要用來選擇特定的服務話，您需要把 /usr/share/logwatch/default.conf/logwatch.conf 文件中的 &quot;Service = All &quot; 這一行註釋掉。</p><p><img src="https://farm6.staticflickr.com/5612/14948933564_94cbc5353c_z.jpg" alt=""></p><pre><code>Format = &lt;text|html&gt;
</code></pre><p>“Format” 配置指令定義了一份 logwatch 報告的格式（比如 text 或者 HTML）。</p><pre><code>Output = &lt;file|mail|stdout&gt;
</code></pre><p>&quot;Output&quot; 配置指令定義生成的 logwatch 報告要發送的目的地。它能被保存成文件（file），生成電子郵件（mail）或者是直接在屏幕上顯示（stdout）。</p><h3 id="用-logwatch-來分析日誌文件" tabindex="-1">用 Logwatch 來分析日誌文件 <a class="header-anchor" href="#用-logwatch-來分析日誌文件" aria-label="Permalink to “用 Logwatch 來分析日誌文件”">​</a></h3><p>要弄明白怎麼使用 logwatch 來分析日誌文件，可以參考下面的 logwatch.conf 文件例子:</p><pre><code>Detail = High
MailTo = youremailaddress@yourdomain.com
Range = Today
Service = http
Service = postfix
Service = zz-disk_space
Format = html
Output = mail
</code></pre><p>使用這些設置，logwatch 將會處理三個應用服務（http、postfix 和 zz-disk_space）當天產生的日誌，生成一份非常詳細的 HTML 格式報告，然後郵件給您。</p><p>如果您不想個性化 /etc/logwatch/conf/logwatch.conf，您可以不修改此文件讓其默認，然後在命令列裏運行如下所示的命令。也會得到同樣的輸出。</p><pre><code># logwatch --detail 10 --mailto youremailaddress@yourdomain.com --range today --service http --service postfix --service zz-disk_space --format html --output mail 
</code></pre><p>電子郵件發送的報告樣子如圖示:</p><p><img src="https://farm6.staticflickr.com/5611/15383540608_57dc37e3d6_z.jpg" alt=""></p><p>這份電子郵件頭部包含指向導航到報告細節的鏈接，在每個選中的服務細節，也會有“返回頂部”的鏈接。</p><p>接收人很少的情況下您可能會使用電子郵件發送報告這個選項。其它情況下，您可能會把讓其生成為 HTML 格式的報告，這樣每個想看這份報告的人都可以從網絡共享裏看到。只需要把上面例子中的配置做些修改就可以實現:</p><pre><code>Detail = High
Range = Today
Service = http
Service = postfix
Service = zz-disk_space
Format = html
Output = file
Filename = /var/www/html/logs/dev1.html
</code></pre><p>同樣的，也可以在命令列中運行如下的命令。</p><pre><code># logwatch --detail 10 --range today --service http --service postfix --service zz-disk_space --format html --output file --filename /var/www/html/logs/dev1.html 
</code></pre><p>最後，讓我們使用 cron 來配置 logwatch 的定時執行任務。下面的例子中，將會在每個工作日的下午 12：15 分運行 logwatch 調度任務。</p><pre><code># crontab -e 
</code></pre><hr><pre><code>15 12 * * 1,2,3,4,5 /sbin/logwatch
</code></pre><p>希望這會有所幫助。歡迎到社區發表評論或分享自己的心得和體會！</p><hr>`,27)),a("p",null,[t[6]||(t[6]=o("via: ",-1)),l(e,{href:"http://xmodulo.com/monitor-log-file-linux-logwatch.html"},{default:r(()=>[...t[5]||(t[5]=[o("http://xmodulo.com/monitor-log-file-linux-logwatch.html",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=o("作者：",-1)),l(e,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...t[7]||(t[7]=[o("Gabriel Cánepa",-1)])]),_:1}),t[11]||(t[11]=o(" 譯者：",-1)),l(e,{href:"https://github.com/runningwater"},{default:r(()=>[...t[8]||(t[8]=[o("runningwater",-1)])]),_:1}),t[12]||(t[12]=o(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[9]||(t[9]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=o("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原創翻譯，",-1)),l(e,{href:"http://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[o("Linux中國",-1)])]),_:1}),t[17]||(t[17]=o(" 榮譽推出",-1))])])}const v=n(c,[["render",d]]);export{L as __pageData,v as default};
